        ];

        $verbForms = [];
        foreach (self::VERB_BASES as $base) {
            foreach (self::conjugate($base) as $form) {
                $verbForms[] = $form;
            }

            // British English: derive "-ize"/"-yze" -> "-ise"/"-yse" automatically
            // (realize -> realise, analyze -> analyse), including all inflected
            // forms - no need to maintain both spellings by hand.
            if (preg_match('/(i|y)ze$/', $base)) {
                $britishBase = mb_substr($base, 0, -2) . 'se';
                foreach (self::conjugate($britishBase) as $form) {
                    $verbForms[] = $form;
                }
            }
        }
        foreach (self::DUAL_L_VERBS as $base) {
            // British "l" doubling (the American form is already produced via
            // VERB_BASES + conjugate(), since these verbs are listed there too)
            $verbForms[] = $base . 'led';
            $verbForms[] = $base . 'ling';
        }
        foreach (self::IRREGULAR as $base => $forms) {
            $verbForms[] = $base;
            foreach ($forms as $form) {
                $verbForms[] = $form;
            }
        }

        // British/American noun & adjective spelling variants, singular + plural
        $spellingVariants = [];
        foreach (self::NOUN_ADJ_VARIANTS as [$british, $american]) {
            $spellingVariants[] = $british;
            $spellingVariants[] = $british . 's';
            $spellingVariants[] = $american;
            $spellingVariants[] = $american . 's';
        }

        $words = array_fill_keys(
            array_merge($functionWords, $adjectives, $verbForms, $spellingVariants),
            true
        );
        return $words;
    }

    /**
     * Generates [base form, 3rd person singular, -ed form, -ing form] via rules.
     * @return string[]
     */
    private static function conjugate(string $base): array
    {
        $forms = [$base];
        $last = mb_substr($base, -1);
        $last2 = mb_substr($base, -2);
        $secondLast = mb_substr($base, -2, 1);

        // 3rd person singular
        if (preg_match('/(s|x|z|ch|sh)$/', $base)) {
            $forms[] = $base . 'es';
        } elseif ($last === 'y' && !self::isVowel($secondLast)) {
            $forms[] = mb_substr($base, 0, -1) . 'ies';
        } else {
            $forms[] = $base . 's';
        }

        // -ed form
        if ($last === 'e') {
            $forms[] = $base . 'd';
        } elseif ($last === 'y' && !self::isVowel($secondLast)) {
            $forms[] = mb_substr($base, 0, -1) . 'ied';
        } elseif (self::doublesConsonant($base)) {
            $forms[] = $base . $last . 'ed';
        } else {
            $forms[] = $base . 'ed';
        }

        // -ing form
        if ($last2 === 'ie') {
            $forms[] = mb_substr($base, 0, -2) . 'ying';
        } elseif ($last === 'e' && !in_array($last2, ['ee', 'oe', 'ye'], true)) {
            $forms[] = mb_substr($base, 0, -1) . 'ing';
        } elseif (self::doublesConsonant($base)) {
            $forms[] = $base . $last . 'ing';
        } else {
            $forms[] = $base . 'ing';
        }

        return $forms;
    }

    private static function isVowel(string $char): bool
    {
        return in_array(mb_strtolower($char), ['a', 'e', 'i', 'o', 'u'], true);
    }

    private static function doublesConsonant(string $base): bool
    {
        return in_array($base, self::DOUBLING_VERBS, true);
    }

    public static function isStopword(string $word): bool
    {
        $set = self::set();
        if (isset($set[$word])) {
            return true;
        }

        // Catch genitive/plural "s" (e.g. proper names: "allans" -> "allan")
        if (mb_strlen($word) > 2 && mb_substr($word, -1) === 's') {
            $stripped = mb_substr($word, 0, -1);
            if (isset($set[$stripped])) {
                return true;
            }
        }

        // Manner adverbs ("actively", "centrally", "quickly", "pleasurably")
        // are treated as stopwords by default - a word ending in "-ly" is
        // assumed to be an adjective+ly adverb unless it's on the LY_EXCEPTIONS allow-list
        // (words that natively end in "-ly" without being derived adverbs,
        // e.g. "family", "early", "friendly").
        if (mb_strlen($word) > 4 && mb_substr($word, -2) === 'ly'
            && !in_array($word, self::LY_EXCEPTIONS, true)) {
            return true;
        }

        return false;
    }
}